    @Test
    public void testEscapeJava_ComplexMix() throws IOException {
        StringWriter out = new StringWriter();
        String input = "Double \" quotes, Single ' quotes, Backslash \\, Newline \n, Return \r, Tab \t";
        String expected = "Double \" quotes, Single ' quotes, Backslash \\\\, Newline \\n, Return \\r, Tab \\t";
        StringEscapeUtils.escapeJava(out, input);
        assertEquals(expected, out.toString());
    }


